def reorder_by_inverse_permutation(items, perm):
    n = len(items)
    result = [None] * n
    for i in range(n):
        result[perm[i]] = items[i]
    return result

def reorder_by_priority_list(items, priority):
    priority_rank = {p: i for i, p in enumerate(priority)}
    in_priority = [it for it in items if it in priority_rank]
    not_in_priority = [it for it in items if it not in priority_rank]
    in_priority_sorted = sorted(in_priority, key=lambda it: priority_rank[it])
    return in_priority_sorted + not_in_priority

def reorder_by_priority_list_unlisted_first(items, priority):
    priority_rank = {p: i for i, p in enumerate(priority)}
    not_in_priority = [it for it in items if it not in priority_rank]
    in_priority = [it for it in items if it in priority_rank]
    in_priority_sorted = sorted(in_priority, key=lambda it: priority_rank[it])
    return not_in_priority + in_priority_sorted

def sort_string_by_custom_order(s, order):
    order_rank = {c: i for i, c in enumerate(order)}
    in_order_chars = [c for c in s if c in order_rank]
    not_in_order_chars = [c for c in s if c not in order_rank]
    in_order_sorted = sorted(in_order_chars, key=lambda c: order_rank[c])
    return ''.join(in_order_sorted) + ''.join(not_in_order_chars)

def move_to_front(items, front):
    remaining = list(items)
    result = []
    for f in front:
        if f in remaining:
            result.append(f)
            remaining.remove(f)
    result.extend(remaining)
    return result

