def bucket_sort_by_decade(nums):
    buckets = defaultdict(list)
    for v in nums:
        decade = (v // 10) * 10
        buckets[decade].append(v)
    result = {}
    for decade in sorted(buckets.keys()):
        result[decade] = sorted(buckets[decade])
    return result

def bucket_count_by_width(nums, width, start):
    if not nums:
        return []
    max_val = max(nums)
    max_bucket = int((max_val - start) // width)
    counts = [0] * (max_bucket + 1)
    for v in nums:
        idx = int((v - start) // width)
        counts[idx] += 1
    return counts

