def bucket_sort_by_sign(nums):
    negative = sorted(v for v in nums if v < 0)
    zero = sorted(v for v in nums if v == 0)
    positive = sorted(v for v in nums if v > 0)
    return {'negative': negative, 'zero': zero, 'positive': positive}

def distribute_into_n_buckets_by_value_range(nums, n):
    if not nums:
        return [[] for _ in range(n)]
    min_v = min(nums)
    max_v = max(nums)
    buckets = [[] for _ in range(n)]
    if max_v == min_v:
        for v in nums:
            buckets[0].append(v)
    else:
        width = (max_v - min_v) / n
        for v in nums:
            if v == max_v:
                idx = n - 1
            else:
                idx = int((v - min_v) // width)
                if idx >= n:
                    idx = n - 1
                if idx < 0:
                    idx = 0
            buckets[idx].append(v)
    for i in range(n):
        buckets[i].sort()
    return buckets

