def min_swaps_to_sort_desc(arr):
    n = len(arr)
    if n == 0:
        return 0
    sorted_arr = sorted(arr, reverse=True)
    pos_in_sorted = {v: i for i, v in enumerate(sorted_arr)}
    visited = [False] * n
    swaps = 0
    for i in range(n):
        if visited[i] or pos_in_sorted[arr[i]] == i:
            visited[i] = True
            continue
        cycle_size = 0
        j = i
        while not visited[j]:
            visited[j] = True
            j = pos_in_sorted[arr[j]]
            cycle_size += 1
        if cycle_size > 0:
            swaps += cycle_size - 1
    return swaps
